<dialog class="entry-dialog quick-dialog" id="contact-{{$profile->id}}" aria-labelledby="contact-title-{{$profile->id}}"><div class="entry-dialog-header"><h2 id="contact-title-{{$profile->id}}">Kişi / kurum bilgileri</h2><button type="button" class="dialog-close" aria-label="Kapat">×</button></div><form class="quick-save" method="post" action="/muhasebe/rehber/{{$profile->id}}"><div class="entry-dialog-body">@csrf<div class="grid"><label>Ad / unvan<input name="name" value="{{$profile->name}}" required maxlength="160"></label><label>Tür<select name="kind"><option value="person" @selected($profile->kind==='person')>Kişi</option><option value="company" @selected($profile->kind==='company')>Kurum</option></select></label></div><div class="grid">@foreach(['email'=>'E-posta','phone'=>'Telefon','tax_office'=>'Vergi dairesi','tax_number'=>'Vergi numarası'] as $field=>$label)<label>{{$label}}<input name="{{$field}}" value="{{$profile->$field}}" type="{{$field==='email'?'email':'text'}}" maxlength="{{$field==='email'?255:($field==='tax_office'?160:40)}}"></label>@endforeach</div><label>Adres<textarea name="address" maxlength="2000">{{$profile->address}}</textarea></label>@include('accounting.tag-field',['tagValue'=>implode(', ',json_decode($profile->tags??'[]',true))])<p class="quick-error" role="alert"></p></div><div class="entry-dialog-footer"><button type="button" class="dialog-close button-secondary">Vazgeç</button><button>Kaydet</button></div></form></dialog>
